      definition: 'عصور التاريخ الفرعوني: دورات حضارية كبرى وثقها مانيتون (30 أسرة) تتنقل بين عصور القوة والمركزية وعصور الاضمحلال والانتقال.',
      trick: 'تريكة الامتحان: الثورة ضد بيبي الثاني حولت معيار تقييم الحاكم؛ فلم يعد الملك يُقدس لذاته أو بصفته إلهاً مطلقاً، بل أصبح يُمدح بقدرته على إقامة العدل وتوفير الأمن لرعيته (الملوكية المقيدة).',
