      quickCapsule: 'العصر العتيق = وحدة القطرين 3200 ق.م وتأسيس منف. الدولة القديمة = الأهرامات وأول ثورة اجتماعية. الدولة الوسطى = رخاء اقتصادي وسد اللاهون وقناة سيزوستريس. الدولة الحديثة = مجد حربي وتأسيس الإمبراطورية. العصر المتأخر = نهضة الأسرة 26 ودوران نخاو حول إفريقيا.',
      directExamTrick: 'نقل أمنمحات الأول للعاصمة إلى "أثيت تاوي" كان له هدف اقتصادي وسياسي معاً: القرب من الدلتا لخدمة الزراعة والسيطرة على مقاليد الحكم.',
