    documentaryScript: `[نبرة هادئة]
شهدت مصر في العصر الوسيط تحولات كبرى أعادت رسم ملامحها السياسية والحضارية، ورسخت مكانتها كقلب نابض للعالم الإسلامي ودرع واقٍ لحضارته.
[توقف قصير]
بدأت هذه الحقبة بالفتح الإسلامي المجيد عام 641 م (20 هـ) بقيادة القائد «عمرو بن العاص»، الذي أطلق عهداً تاريخياً من التسامح الديني والأمان؛ فأمّن بطريرك الأقباط «الأنبا بنيامين» وأعاده إلى مقره الكنسي بالإسكندرية بعد ثلاثة عشر عاماً من المطاردة والاختباء في الصحراء هرباً من البطش الروماني البيزنطي، وألغى الجزية عن الرهبان والشيوخ والفقراء، معلناً حرية العقيدة وحماية الكنائس.
[نبرة حماسية]
ومع ضعف الخلافة العباسية في بغداد، انطلقت تجربة «الدول المستقلة» التي جعلت من مصر مركزاً مستقلاً للثقل السياسي:
بدأت بالدولة الطولونية عام 868 م على يد «أحمد بن طولون»، ثم الإخشيدية، وصولاً إلى الدولة الفاطمية عام 969 م حين بنى القائد «جوهر الصقلي» مدينة القاهرة لتكون عاصمة للخلافة، وشيد «الجامع الأزهر» عام 972 م ليتحول سريعاً إلى أعظم جامعة إسلامية ومنارة لحفظ اللغة العربية والهوية الوطنية.
ثم سطع نجم الدولة الأيوبية عام 1171 م بقيادة الناصر «صلاح الدين الأيوبي» الذي وحد مصر والشام وحقق النصر التاريخي في معركة «حطين» عام 1187 م واسترد القدس الشريف، لتخلفها دولة المماليك عام 1250 م التي تصدت لأعتى خطرين واجها الإنسانية: فدحر «سيف الدين قطز» المغول في معركة «عين جالوت» الخالدة عام 1260 م، وقضى سلاطين المماليك على آخر بقايا الصليبيين.
[وقفة تأملية]
وعلى امتداد العصر الوسيط، تتابعت أربع عواصم إسلامية كبرى في تناسق عمراني فريد: من «الفسطاط»، ثم «العسكر»، ثم «القطائع»، وتوجت جميعاً بـ «القاهرة». وشهدت مصر تعريب الدواوين وسيادة اللغة العربية، وتألقت تجارة «الكارمي» التي جعلت من تجار مصر حلقة الوصل المحتكرة للتجارة بين الهند وإفريقيا وأوروبا، حتى تحول طريق رأس الرجاء الصالح وسقطت دولة المماليك عام 1517 م.
أكاديمية المنارة التعليمية | «هنذاكر التاريخ الوطني سوا» 🎯 | واتساب: 01097083710`,
