    documentaryScript: `[نبرة هادئة]
عاش القرن العشرون في مصر ملحمة متصلة من الثورات الشعبية والصمود العسكري والتحولات الجذرية التي صنعت مصير الوطن الحديث.
[توقف قصير]
انطلقت الشرارة الكبرى في ثورة 1919م؛ أول ثورة قومية مدنية خالصة أعلنت ولادة الأمة المصرية الموحدة، ورفعت شعار الهلال مع الصليب، وشهدت خروج المرأة المصرية، لتنتزع تصريح 28 فبراير 1922م الذي أنهى الحماية البريطانية شكلياً، ودستور 1923م الذي أرسى مبدأ البرلمانية.
[نبرة حماسية]
ومع استمرار فساد الأحزاب والاحتلال ومأساة الأسلحة الفاسدة في حرب فلسطين 1948م، فجر تنظيم الضباط الأحرار ثورة 23 يوليو 1952م بمبادئها الستة الخالدة: القضاء على الإقطاع والاستعمار والاحتكار، وإقامة جيش وطني قوي وعدالة اجتماعية وحياة ديمقراطية سليمة.
فأصدرت قانون الإصلاح الزراعي، وبنت السد العالي، وأممت شركة قناة السويس عام 1956م، وتصدت للعدوان الثلاثي، وساندت حركات التحرر في إفريقيا والعالم العربي.
[وقفة تأملية]
وبعد نكسة 1967م، أثبتت مصر أن أمتها عصية على الانكسار؛ فخاضت حرب الاستنزاف المجيدة، وصولاً إلى اليوم المشهود: العاشر من رمضان، السادس من أكتوبر عام 1973م.
حين عبرت القوات المسلحة المصرية قناة السويس، وحطمت خط بارليف الحصين في ست ساعات بمضخات المياه والتخطيط العلمي المحكم، في أكبر معركة أسلحة مشتركة أسقطت نظرية الأمن الإسرائيلي وأعادت لمصر والعرب كرامتهم وسيادتهم الكاملة على سيناء الحبيبة.
أكاديمية المنارة التعليمية | «هنذاكر تاريخ مصر والعرب سوا» 🎯 | واتساب: 01097083710`,
